/**
 * server/routes/face.js
 * Face registration and verification routes
 * Uses real 128-d face descriptors generated by browser-side face-api models.
 */

import express from 'express';

const router = express.Router();

import { ObjectId } from 'mongodb';
import { connectToDatabase, COLLECTIONS } from '../db/mongoAtlas.js';
import { authMiddleware } from '../middleware/auth.js';
import { broadcastAttendanceUpdated } from '../services/broadcast.js';

const DESCRIPTOR_LENGTH = 128;
const FACE_MATCH_THRESHOLD = Number(process.env.FACE_MATCH_THRESHOLD || 0.62);
const MIN_DETECTION_SCORE = Number(process.env.FACE_MIN_DETECTION_SCORE || 0.45);
const FRONTEND_MODELS_PATH = '/models';
const FRONTEND_REQUIRED_MODEL_FILES = [
  'ssd_mobilenetv1_model-weights_manifest.json',
  'ssd_mobilenetv1_model-shard1',
  'ssd_mobilenetv1_model-shard2',
  'face_landmark_68_model-weights_manifest.json',
  'face_landmark_68_model-shard1',
  'face_recognition_model-weights_manifest.json',
  'face_recognition_model-shard1',
  'face_recognition_model-shard2',
];

function decodeBase64Image(base64String) {
  const base64Data = base64String.replace(/^data:image\/\w+;base64,/, '');
  return Buffer.from(base64Data, 'base64');
}

function normalizeEmbedding(embedding) {
  const sum = Math.sqrt(embedding.reduce((acc, value) => acc + value * value, 0));
  if (!sum || !Number.isFinite(sum)) {
    throw new Error('Invalid face descriptor magnitude');
  }
  return embedding.map((value) => value / sum);
}

function validateDescriptor(faceDescriptor) {
  if (!Array.isArray(faceDescriptor)) {
    throw new Error('Face descriptor is required');
  }
  if (faceDescriptor.length !== DESCRIPTOR_LENGTH) {
    throw new Error(`Face descriptor must have ${DESCRIPTOR_LENGTH} values`);
  }
  if (!faceDescriptor.every((value) => typeof value === 'number' && Number.isFinite(value))) {
    throw new Error('Face descriptor contains invalid values');
  }
  return normalizeEmbedding(faceDescriptor);
}

async function generateEmbedding(_imageBuffer, faceDescriptor) {
  return validateDescriptor(faceDescriptor);
}

async function compareEmbeddings(embedding1, embedding2) {
  if (embedding1.length !== embedding2.length) {
    return 0;
  }

  let dotProduct = 0;
  let norm1 = 0;
  let norm2 = 0;

  for (let index = 0; index < embedding1.length; index += 1) {
    dotProduct += embedding1[index] * embedding2[index];
    norm1 += embedding1[index] * embedding1[index];
    norm2 += embedding2[index] * embedding2[index];
  }

  return dotProduct / (Math.sqrt(norm1) * Math.sqrt(norm2));
}

async function checkLiveness(imageBuffer, metadata = {}) {
  const byteSize = imageBuffer.length;
  const detectionScore = typeof metadata?.detectionScore === 'number' ? metadata.detectionScore : null;
  const sizePassed = byteSize >= 15 * 1024;
  const detectionPassed = detectionScore == null || detectionScore >= MIN_DETECTION_SCORE;
  const passed = sizePassed && detectionPassed;

  return {
    passed,
    score: detectionScore ?? (sizePassed ? 0.7 : 0.2),
    method: 'client-face-api-descriptor',
    message: passed
      ? 'Descriptor and capture quality checks passed'
      : 'Face capture quality too low. Use better lighting and keep one face centered.',
  };
}

function requireAdmin(req, res) {
  if (req.user?.role !== 'admin') {
    res.status(403).json({ error: 'Administrator access required' });
    return false;
  }
  return true;
}

export async function registerFaceForAuth(userId, faceImage, metadata = {}, faceDescriptor = null) {
  const db = await connectToDatabase();
  const userObjectId = ObjectId.isValid(userId) ? new ObjectId(userId) : null;
  const userFilter = userObjectId ? { _id: userObjectId } : { id: userId };

  const user = await db.collection(COLLECTIONS.USERS).findOne(userFilter);
  if (!user) {
    throw new Error('User not found');
  }

  const existing = await db.collection(COLLECTIONS.FACE_EMBEDDINGS).findOne({ userId });
  const imageBuffer = decodeBase64Image(faceImage);
  const embedding = await generateEmbedding(imageBuffer, faceDescriptor);
  const liveness = await checkLiveness(imageBuffer, metadata);

  if (!liveness.passed) {
    throw new Error(liveness.message);
  }

  const now = new Date();
  const record = {
    userId,
    embedding,
    embeddingVersion: 'face-api-128d-v1',
    embeddingSource: 'browser-face-api',
    descriptorModel: metadata?.descriptorModel || 'face-api-ssd-mobilenetv1',
    detectionScore: metadata?.detectionScore ?? null,
    livenessScore: liveness.score,
    livenessPassed: liveness.passed,
    faceImageBase64: faceImage,
    metadata,
    updatedAt: now,
  };

  if (existing) {
    await db.collection(COLLECTIONS.FACE_EMBEDDINGS).updateOne(
      { userId },
      { $set: record, $setOnInsert: { createdAt: existing.createdAt || now } }
    );
  } else {
    await db.collection(COLLECTIONS.FACE_EMBEDDINGS).insertOne({
      ...record,
      createdAt: now,
    });
  }

  await db.collection(COLLECTIONS.USERS).updateOne(
    userFilter,
    { $set: { faceImage, faceRegistered: true, updatedAt: now } }
  );

  return {
    ok: true,
    userId,
    embeddingStored: true,
    livenessPassed: liveness.passed,
    detectionScore: metadata?.detectionScore ?? null,
    id: existing?._id?.toString() || null,
  };
}

router.post('/register', authMiddleware, async (req, res) => {
  try {
    const { userId, faceImage, metadata, faceDescriptor } = req.body;

    if (!userId || !faceImage) {
      return res.status(400).json({ error: 'userId and faceImage (Base64) are required' });
    }

    const result = await registerFaceForAuth(userId, faceImage, metadata || {}, faceDescriptor);
    res.status(201).json(result);
  } catch (error) {
    console.error('Face register error:', error);
    if (error.message === 'User not found') {
      return res.status(404).json({ error: error.message });
    }
    if (error.message.includes('descriptor') || error.message.includes('quality') || error.message.includes('lighting')) {
      return res.status(400).json({ error: error.message });
    }
    res.status(500).json({ error: `Failed to register face: ${error.message}` });
  }
});

router.post('/verify', authMiddleware, async (req, res) => {
  try {
    const { userId, faceImage, faceDescriptor, metadata = {}, recordAttendance = false, sessionId, classId, location } = req.body;

    if (!userId || !faceImage) {
      return res.status(400).json({ error: 'userId and faceImage (Base64) are required' });
    }

    const db = await connectToDatabase();
    const storedFace = await db.collection(COLLECTIONS.FACE_EMBEDDINGS).findOne({ userId });
    if (!storedFace) {
      return res.status(404).json({ error: 'No registered face found for user', authenticated: false });
    }

    const imageBuffer = decodeBase64Image(faceImage);
    const embedding = await generateEmbedding(imageBuffer, faceDescriptor);
    const similarity = await compareEmbeddings(storedFace.embedding, embedding);
    const liveness = await checkLiveness(imageBuffer, metadata);
    const authenticated = similarity >= FACE_MATCH_THRESHOLD && liveness.passed;

    await db.collection(COLLECTIONS.AUDIT_FACE_VERIFY).insertOne({
      userId,
      similarity: parseFloat(similarity.toFixed(4)),
      threshold: FACE_MATCH_THRESHOLD,
      detectionScore: metadata?.detectionScore ?? null,
      livenessScore: liveness.score,
      livenessPassed: liveness.passed,
      authenticated,
      timestamp: new Date(),
      location: location || null,
      embeddingSource: 'browser-face-api',
    });

    if (recordAttendance && authenticated && sessionId) {
      const attendanceRecord = {
        studentId: userId,
        classId: classId || null,
        sessionId,
        status: 'Present',
        verificationMethod: 'face',
        confidence: parseFloat(similarity.toFixed(2)),
        timestamp: new Date(),
        createdAt: new Date(),
        _id: new ObjectId(),
      };

      await db.collection(COLLECTIONS.ATTENDANCE).insertOne(attendanceRecord);

      broadcastAttendanceUpdated(userId, {
        id: attendanceRecord._id.toString(),
        status: 'Present',
        sessionId,
        classId,
        verified: true,
      });
    }

    res.json({
      authenticated,
      confidence: parseFloat(similarity.toFixed(2)),
      livenessPassed: liveness.passed,
      threshold: FACE_MATCH_THRESHOLD,
      detectionScore: metadata?.detectionScore ?? null,
      method: 'browser-face-api-descriptor',
    });
  } catch (error) {
    console.error('Face verify error:', error);
    const isClientQualityError =
      error.message.includes('descriptor') || error.message.includes('quality') || error.message.includes('lighting');
    res.status(isClientQualityError ? 400 : 500).json({ error: `Failed to verify face: ${error.message}` });
  }
});

router.get('/health', authMiddleware, async (req, res) => {
  if (!requireAdmin(req, res)) {
    return;
  }

  res.json({
    ok: true,
    verifier: {
      mode: 'browser-face-api-descriptor',
      descriptorLength: DESCRIPTOR_LENGTH,
      matchThreshold: FACE_MATCH_THRESHOLD,
      minDetectionScore: MIN_DETECTION_SCORE,
      embeddingVersion: 'face-api-128d-v1',
    },
    frontendModels: {
      basePath: FRONTEND_MODELS_PATH,
      requiredFiles: FRONTEND_REQUIRED_MODEL_FILES,
    },
    timestamp: new Date().toISOString(),
  });
});

router.get('/list', authMiddleware, async (req, res) => {
  try {
    const db = await connectToDatabase();
    const { search, page = '1', limit = '50' } = req.query;

    const filter = {};
    if (search) {
      filter.userId = { $regex: search, $options: 'i' };
    }

    const pageNum = Math.max(1, parseInt(page, 10));
    const limitNum = Math.min(100, Math.max(1, parseInt(limit, 10)));
    const skip = (pageNum - 1) * limitNum;

    const [faces, total] = await Promise.all([
      db.collection(COLLECTIONS.FACE_EMBEDDINGS)
        .find(filter, { projection: { embedding: 0, faceImageBase64: 0 } })
        .sort({ createdAt: -1 })
        .skip(skip)
        .limit(limitNum)
        .toArray(),
      db.collection(COLLECTIONS.FACE_EMBEDDINGS).countDocuments(filter),
    ]);

    res.json({
      ok: true,
      faces: faces.map((face) => ({
        userId: face.userId,
        registered: true,
        timestamp: face.createdAt,
        livenessPassed: face.livenessPassed,
        detectionScore: face.detectionScore ?? null,
        embeddingSource: face.embeddingSource || 'browser-face-api',
      })),
      pagination: {
        page: pageNum,
        limit: limitNum,
        total,
        totalPages: Math.ceil(total / limitNum),
      },
    });
  } catch (error) {
    console.error('Face list error:', error);
    res.status(500).json({ error: 'Failed to list faces' });
  }
});

router.get('/:userId', authMiddleware, async (req, res) => {
  try {
    const { userId } = req.params;
    const db = await connectToDatabase();

    const face = await db.collection(COLLECTIONS.FACE_EMBEDDINGS).findOne(
      { userId },
      { projection: { embedding: 0 } }
    );

    if (!face) {
      return res.status(404).json({ error: 'Face not found for user' });
    }

    res.json({
      ok: true,
      userId: face.userId,
      image: face.faceImageBase64 || null,
      createdAt: face.createdAt,
      livenessPassed: face.livenessPassed,
      detectionScore: face.detectionScore ?? null,
      embeddingSource: face.embeddingSource || 'browser-face-api',
    });
  } catch (error) {
    console.error('Face get error:', error);
    res.status(500).json({ error: 'Failed to get face' });
  }
});

router.delete('/:userId', authMiddleware, async (req, res) => {
  try {
    const { userId } = req.params;
    const db = await connectToDatabase();

    const result = await db.collection(COLLECTIONS.FACE_EMBEDDINGS).deleteOne({ userId });

    if (result.deletedCount === 0) {
      return res.status(404).json({ error: 'Face record not found' });
    }

    await db.collection(COLLECTIONS.USERS).updateOne(
      { _id: new ObjectId(userId) },
      { $set: { faceRegistered: false, updatedAt: new Date() }, $unset: { faceImage: '' } }
    );

    res.json({ ok: true, deleted: true });
  } catch (error) {
    console.error('Face delete error:', error);
    res.status(500).json({ error: 'Failed to delete face' });
  }
});

router.post('/liveness/challenge', authMiddleware, async (req, res) => {
  try {
    const challenge = {
      type: 'blink',
      instructions: 'Please blink slowly',
      expiresAt: new Date(Date.now() + 30000),
    };

    res.json({ ok: true, challenge });
  } catch (error) {
    console.error('Liveness challenge error:', error);
    res.status(500).json({ error: 'Failed to create liveness challenge' });
  }
});

router.post('/liveness/verify', authMiddleware, async (req, res) => {
  try {
    const { faceImage, metadata = {} } = req.body;
    if (!faceImage) {
      return res.status(400).json({ error: 'faceImage is required' });
    }

    const imageBuffer = decodeBase64Image(faceImage);
    const result = await checkLiveness(imageBuffer, metadata);

    res.json({
      ok: true,
      passed: result.passed,
      score: result.score,
      method: result.method,
      message: result.message,
    });
  } catch (error) {
    console.error('Liveness verify error:', error);
    res.status(500).json({ error: 'Failed to verify liveness' });
  }
});

export async function verifyFaceForAuth(userId, faceImage, faceDescriptor = null, metadata = {}) {
  const db = await connectToDatabase();
  const storedFace = await db.collection(COLLECTIONS.FACE_EMBEDDINGS).findOne({ userId });

  if (!storedFace) {
    return { authenticated: false, error: 'No registered face found for user' };
  }

  const imageBuffer = decodeBase64Image(faceImage);
  const embedding = await generateEmbedding(imageBuffer, faceDescriptor);
  const similarity = await compareEmbeddings(storedFace.embedding, embedding);
  const liveness = await checkLiveness(imageBuffer, metadata);
  const authenticated = similarity >= FACE_MATCH_THRESHOLD && liveness.passed;

  return {
    authenticated,
    confidence: parseFloat(similarity.toFixed(2)),
    livenessPassed: liveness.passed,
    method: 'browser-face-api-descriptor',
  };
}

export default router;
